#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/drivers/rtc.h>
#include <time.h>

#define RTC_NODE DT_ALIAS(rtc)

#define ALARM_ID 0

/* 1 second in the future */
#define ALARM_DELAY_S 1
/* 100 ms */
#define TICK_PERIOD_MS 100
/* Wait up to 2 seconds for the alarm */
#define ALARM_TIMEOUT_MS 2000

static const struct device *dev = DEVICE_DT_GET(RTC_NODE);
static struct k_sem alarm_sem;
static volatile bool alarm_fired;

static void alarm_callback(const struct device *dev, uint16_t id, void *user_data)
{
	ARG_UNUSED(dev);
	ARG_UNUSED(id);

	*(bool *)user_data = true;
	k_sem_give(&alarm_sem);
}

static int set_alarm_abs(const uint16_t id, const struct rtc_time *alarm_time)
{
	return rtc_set_alarm(dev, id, 0, alarm_time);
}

static int set_alarm_rel(const uint16_t id, const uint16_t mask, const struct rtc_time *alarm_time)
{
	return rtc_set_alarm(dev, id, mask, alarm_time);
}

static void *rtc_api_setup(void)
{
	k_object_access_grant(dev, k_current_get());

	if (rtc_get_num_alarms(dev) == 0) {
		ztest_skip();
	}

	k_sem_init(&alarm_sem, 0, 1);

	return NULL;
}

static void rtc_api_before(void *data)
{
	ARG_UNUSED(data);

	alarm_fired = false;
	k_sem_reset(&alarm_sem);

	/* Disable alarm to prevent it from firing unexpectedly */
	(void)rtc_disable_alarm(dev, ALARM_ID);
}

static void get_alarm_abs(struct rtc_time *timeptr)
{
	int ret;

	ret = rtc_get_time(dev, timeptr);
	zassert_ok(ret, "Failed to get RTC time");

	timeptr->tm_sec += ALARM_DELAY_S;
	if (timeptr->tm_sec >= 60) {
		timeptr->tm_sec -= 60;
		timeptr->tm_min += 1;
		if (timeptr->tm_min >= 60) {
			timeptr->tm_min = 0;
			timeptr->tm_hour += 1;
			if (timeptr->tm_hour >= 24) {
				timeptr->tm_hour = 0;
			}
		}
	}
}

ZTEST(rtc_api, test_alarm)
{
	struct rtc_time alarm_time;
	int ret;

	get_alarm_abs(&alarm_time);

	ret = set_alarm_abs(ALARM_ID, &alarm_time);
	zassert_ok(ret, "Failed to set alarm");

	k_sleep(K_SECONDS(ALARM_DELAY_S) + K_MSEC(TICK_PERIOD_MS));

	ret = rtc_alarm_is_pending(dev, ALARM_ID);
	zassert_equal(ret, 1, "Alarm should be pending");

	ret = rtc_disable_alarm(dev, ALARM_ID);
	zassert_ok(ret, "Failed to disable alarm");

	ret = rtc_alarm_is_pending(dev, ALARM_ID);
	zassert_equal(ret, 0, "Alarm should not be pending");
}

ZTEST(rtc_api, test_alarm_callback)
{
	struct rtc_time alarm_time;
	int ret;

	get_alarm_abs(&alarm_time);

	ret = rtc_set_alarm_callback(dev, ALARM_ID, alarm_callback, (void *)&alarm_fired);
	zassert_ok(ret, "Failed to set alarm callback");

	ret = set_alarm_abs(ALARM_ID, &alarm_time);
	zassert_ok(ret, "Failed to set alarm");

	ret = k_sem_take(&alarm_sem, K_MSEC(ALARM_TIMEOUT_MS));
	zassert_ok(ret, "Alarm did not fire");
	zassert_true(alarm_fired, "Alarm callback did not run");

	ret = rtc_disable_alarm(dev, ALARM_ID);
	zassert_ok(ret, "Failed to disable alarm");
}

ZTEST(rtc_api, test_alarm_relative)
{
	struct rtc_time alarm_time = {
		.tm_sec = ALARM_DELAY_S,
	};
	uint16_t mask = RTC_ALARM_TIME_MASK_SECOND;
	int ret;

	ret = rtc_set_alarm_callback(dev, ALARM_ID, alarm_callback, (void *)&alarm_fired);
	zassert_ok(ret, "Failed to set alarm callback");

	ret = set_alarm_rel(ALARM_ID, mask, &alarm_time);
	zassert_ok(ret, "Failed to set relative alarm");

	ret = k_sem_take(&alarm_sem, K_MSEC(ALARM_TIMEOUT_MS));
	zassert_ok(ret, "Alarm did not fire");
	zassert_true(alarm_fired, "Alarm callback did not run");

	ret = rtc_disable_alarm(dev, ALARM_ID);
	zassert_ok(ret, "Failed to disable alarm");
}

ZTEST(rtc_api, test_set_alarm_invalid_id)
{
	uint16_t num_alarms = rtc_get_num_alarms(dev);
	struct rtc_time alarm_time;
	int ret;

	alarm_time.tm_sec = 0;

	ret = set_alarm_abs(num_alarms, &alarm_time);
	zassert_equal(ret, -EINVAL, "rtc_set_alarm with id=%u should have failed", num_alarms);
}

ZTEST(rtc_api, test_disable_alarm_invalid_id)
{
	uint16_t num_alarms = rtc_get_num_alarms(dev);
	int ret;

	ret = rtc_disable_alarm(dev, num_alarms);
	zassert_equal(ret, -EINVAL, "rtc_disable_alarm with id=%u should have failed",
		      num_alarms);
}

ZTEST(rtc_api, test_set_alarm_callback_invalid_id)
{
	uint16_t num_alarms = rtc_get_num_alarms(dev);
	int ret;

	ret = rtc_set_alarm_callback(dev, num_alarms, alarm_callback, NULL);
	zassert_equal(ret, -EINVAL, "rtc_set_alarm_callback with id=%u should have failed",
		      num_alarms);
}

ZTEST(rtc_api, test_alarm_is_pending_invalid_id)
{
	uint16_t num_alarms = rtc_get_num_alarms(dev);
	int ret;

	ret = rtc_alarm_is_pending(dev, num_alarms);
	zassert_false(ret > 0, "rtc_alarm_is_pending with id=%u should have failed or returned 0",
		      num_alarms);
}

ZTEST_SUITE(rtc_api, NULL, rtc_api_setup, rtc_api_before, NULL, NULL);
